INSERT OR REPLACE INTO lessons (id, course_id, title_thai, title_phonetic, title_english, title_myanmar, dialogue, grammar, quizzes) VALUES (
    '',
    'course-basic',
    'การแนะนำตัว',
    'kaan næ-nam tua',
    'Lesson 1: Introductions',
    'သင်ခန်းစာ ၁ - မိမိကိုယ်မိမိ မိတ်ဆက်ခြင်း',
    '[{"speaker":"A","thai":"คุณชื่ออะไรครับ","phonetic":"khun chue a-rai khráp","english":"What is your name?","myanmar":"မင်းနာမည်ဘာလဲခင်ဗျာ။","words":[{"thai":"คุณ","phonetic":"khun","english":"you / Mr. / Ms.","myanmar":"သင် / မင်း","partOfSpeech":"pronoun"},{"thai":"ชื่อ","phonetic":"chue","english":"name / to be named","myanmar":"နာမည် / အမည်","partOfSpeech":"noun"},{"thai":"อะไร","phonetic":"a-rai","english":"what","myanmar":"ဘာလဲ","partOfSpeech":"pronoun"},{"thai":"ครับ","phonetic":"khráp","english":"polite particle (male)","myanmar":"ခင်ဗျာ","partOfSpeech":"particle"}]},{"speaker":"B","thai":"ผมชื่อมินครับ","phonetic":"phom chue Min khráp","english":"My name is Min.","myanmar":"ကျွန်တော့်နာမည်မင်း ဖြစ်ပါတယ်ခင်ဗျာ။","words":[{"thai":"ผม","phonetic":"phom","english":"I (male)","myanmar":"ကျွန်တော်","partOfSpeech":"pronoun"},{"thai":"มิน","phonetic":"Min","english":"Min (name)","myanmar":"မင်း","partOfSpeech":"proper noun"}]},{"speaker":"A","thai":"มาจากไหนคะ","phonetic":"maa jaak nai khá","english":"Where do you come from?","myanmar":"ဘယ်ကလာလဲရှင်။","words":[{"thai":"มาจาก","phonetic":"maa jaak","english":"come from","myanmar":"မှ လာသည်","partOfSpeech":"verb"},{"thai":"ไหน","phonetic":"nai","english":"where","myanmar":"ဘယ် / ဘယ်မှာ","partOfSpeech":"pronoun"},{"thai":"คะ","phonetic":"khá","english":"polite particle for question (female)","myanmar":"ရှင်","partOfSpeech":"particle"}]},{"speaker":"B","thai":"มาจากพม่าค่ะ","phonetic":"maa jaak pha-maa khâ","english":"I come from Myanmar.","myanmar":"မြန်မာပြည်က လာတာပါရှင်။","words":[{"thai":"พม่า","phonetic":"pha-maa","english":"Myanmar","myanmar":"မြန်မာ","partOfSpeech":"noun"},{"thai":"ค่ะ","phonetic":"khâ","english":"polite particle for statement (female)","myanmar":"ရှင်","partOfSpeech":"particle"}]}]',
    '[{"title":"1. The Polite Final Particle ''ครับ'' (khráp) for Males","titleMyanmar":"အမျိုးသားသုံး ယဉ်ကျေးသည့် အဆုံးသတ် စကားလုံး ''ครับ'' (ခရပ်)","explanation":"Male speakers use ''ครับ'' (khráp) at the end of sentences for politeness, in both questions and replies.","explanationMyanmar":"အမျိုးသားဖြစ်ပါက မေးခွန်းမေးလျှင်ဖြစ်စေ၊ အဖြေပေးလျှင်ဖြစ်စေ ယဉ်ကျေးစေရန် စကားစုအဆုံးတွင် ''ครับ'' ကို သုံးစွဲရသည်။","examples":[{"thai":"สวัสดีครับ","phonetic":"sa-wat-dii khráp","english":"Hello.","myanmar":"မင်္ဂလာပါခင်ဗျာ။"},{"thai":"ขอบคุณครับ","phonetic":"khɔ̀ɔp-khun khráp","english":"Thank you.","myanmar":"ကျေးဇူးတင်ပါတယ်ခင်ဗျာ။"},{"thai":"สบายดีครับ","phonetic":"sa-baaj-dii khráp","english":"I am fine.","myanmar":"နေကောင်းပါတယ်ခင်ဗျာ။"},{"thai":"ยินดีครับ","phonetic":"yin-dii khráp","english":"My pleasure.","myanmar":"ဝမ်းမြောက်ဝမ်းသာပါခင်ဗျာ။"},{"thai":"ขอโทษครับ","phonetic":"khɔ̌ɔ-thôot khráp","english":"I''m sorry / Excuse me.","myanmar":"တောင်းပန်ပါတယ်/ခွင့်ပြုပါခင်ဗျာ။"},{"thai":"ใช่ครับ","phonetic":"châj khráp","english":"Yes, that''s correct.","myanmar":"ဟုတ်ကဲ့ပါခင်ဗျာ။"}]},{"title":"2. The Polite Final Particle ''ค่ะ'' (khâ) & ''คะ'' (khá) for Females","titleMyanmar":"အမျိုးသမီးသုံး ယဉ်ကျေးသည့် အဆုံးသတ် စကားလုံး ''ค่ะ'' (ခ့တ်) နှင့် ''คะ'' (ခတ်)","explanation":"Female speakers use ''ค่ะ'' (khâ) with a falling tone for statements, and ''คะ'' (khá) with a high tone for questions/calls.","explanationMyanmar":"အမျိုးသမီးများသည် အကြောင်းပြန်ကြားဝါကျတွင် ''ค่ะ'' (အသံနှိမ့်ဖိယတ်) ကိုသုံးပြီး၊ မေးခွန်းဝါကျတွင် ''คะ'' (အသံမြင့်သံပြတ်) ကို ခွဲခြားသုံးစွဲရသည်။","examples":[{"thai":"สวัสดีค่ะ","phonetic":"sa-wat-dii khâ","english":"Hello.","myanmar":"မင်္ဂလာပါရှင်။"},{"thai":"ขอบคุณค่ะ","phonetic":"khɔ̀ɔp-khun khâ","english":"Thank you.","myanmar":"ကျေးဇူးတင်ပါတယ်ရှင်။"},{"thai":"เข้าใจแล้วค่ะ","phonetic":"khâo-cay lɛ́ɛw khâ","english":"I understand now.","myanmar":"နားလည်ပါပြီရှင်။"},{"thai":"สบายดีไหมคะ","phonetic":"sa-baaj-dii mǎi khá","english":"Are you fine?","myanmar":"နေကောင်းလားရှင်။"},{"thai":"ชื่ออะไรคะ","phonetic":"chʉ̂ʉ a-rai khá","english":"What is your name?","myanmar":"နာမည်ဘယ်လိုခေါ်လဲရှင်။"},{"thai":"ยินดีค่ะ","phonetic":"yin-dii khâ","english":"My pleasure.","myanmar":"ဝမ်းမြောက်စွာ ကူညီပါရစေရှင်။"}]},{"title":"3. Direct Name Declaring with ''ชื่อ'' (chʉ̂ʉ) & Title prefix ''คุณ'' (khun)","titleMyanmar":"မိတ်ဆက်ခြင်းအသုံးအနှုန်း- ''ชื่อ'' (ချုး - အမည်ခေါ်သည်) နှင့် ''คุณ'' (ခွန် - လူကြီးမင်း)","explanation":"Use ''ชื่อ'' (chʉ̂ʉ) to declare a name. ''คุณ'' (khun) acts as an honorific prefix like ''Mr./Ms.'' or ''မင်း/ဦး''.","explanationMyanmar":"ကိုယ့်အမည်ကို ပြောလိုလျှင် ''ชื่อ'' (ချုး) ကို သုံးပြီး၊ တစ်ဖက်သားကို ရိုသေစွာခေါ်ဝေါ်လျှင် ''คุณ'' (ခွန်) ကို နာမည်ရှေ့က တွဲသုံးရသည်။","examples":[{"thai":"คุณชื่ออะไรครับ","phonetic":"khun chʉ̂ʉ a-rai khráp","english":"What is your name?","myanmar":"မင်းနာမည်ဘယ်လိုခေါ်လဲခင်ဗျာ။"},{"thai":"ผมชื่อมินครับ","phonetic":"phǒm chʉ̂ʉ min khráp","english":"My name is Min.","myanmar":"ကျွန်တော့်နာမည် မင်း ဖြစ်ပါတယ်ခင်ဗျာ။"},{"thai":"ฉันชื่อมะลิค่ะ","phonetic":"chǎn chʉ̂ʉ má-lí khâ","english":"My name is Mali.","myanmar":"ကျွန်မနာမည် မလိ ဖြစ်ပါတယ်ရှင်။"},{"thai":"คุณมินสบายดีไหมครับ","phonetic":"khun min sa-baaj-dii mǎi khráp","english":"Mr. Min, are you doing fine?","myanmar":"ဦးမင်း နေကောင်းလားခင်ဗျာ။"},{"thai":"น้องชื่ออะไรคะ","phonetic":"nɔ́ɔŋ chʉ̂ʉ a-rai khá","english":"What is your name, little one?","myanmar":"မောင်လေး/ညီမလေး နာမည်ဘယ်လိုခေါ်လဲရှင်။"},{"thai":"พี่ชื่อสมชายครับ","phonetic":"pîi chʉ̂ʉ sǒm-chaaj khráp","english":"My name is Somchai (older brother).","myanmar":"အစ်ကို့နာမည် စုမ်ချိုင်း ပါခင်ဗျာ။"}]},{"title":"4. Personal Pronouns: ผม (phǒm) vs ดิฉัน/ฉัน (dì-chán/chán)","titleMyanmar":"နာမ်စားအသုံးများ- ''ผม'' (ဖုမ် - ကျွန်တော်) ၊ ''ดิฉัน/ฉัน'' (ဒိချန်း/ချန်း - ကျွန်မ)","explanation":"Males refer to themselves as ''ผม'' (phǒm). Females use ''ฉัน'' (chán) or ''ดิฉัน'' (dì-chán) formally.","explanationMyanmar":"အမျိုးသားများက ကိုယ့်ကိုယ်ကိုယ် ''ผม'' ဟုသုံးပြီး၊ အမျိုးသမီးများက ''ฉัน'' သို့မဟုတ် ပိုမိုယဉ်ကျေးလိုလျှင် ''ดิฉัน'' ဟု သုံးစွဲကြသည်။","examples":[{"thai":"ผมมาจากพม่าครับ","phonetic":"phǒm maa jaak pha-maa khráp","english":"I come from Myanmar (male).","myanmar":"ကျွန်တော် မြန်မာပြည်က လာတာပါခင်ဗျာ။"},{"thai":"ฉันมาจากย่างกุ้งค่ะ","phonetic":"chǎn maa jaak jâaŋ-kûŋ khâ","english":"I come from Yangon (female).","myanmar":"ကျွန်မ ရန်ကုန်က လာတာပါရှင်။"},{"thai":"ผมยินดีที่ได้เจอครับ","phonetic":"phǒm yin-dii thîi dâaj cəə khráp","english":"I am happy to meet you.","myanmar":"မင်းနဲ့ဆုံရတာ ကျွန်တော် ဝမ်းသာပါတယ်ခင်ဗျာ။"},{"thai":"ฉันสบายดีค่ะ","phonetic":"chǎn sa-baaj-dii khâ","english":"I am fine (female).","myanmar":"ကျွန်မ နေကောင်းပါတယ်ရှင်။"},{"thai":"คุณล่ะครับ","phonetic":"khun lâ khráp","english":"How about you?","myanmar":"မင်းကောခင်ဗျာ။"},{"thai":"ดิฉันชื่อสุชาดาค่ะ","phonetic":"dì-chán chʉ̂ʉ sù-chaa-daa khâ","english":"My name is Suchada (formal female).","myanmar":"ကျွန်မအမည် စုချာဒါး ဖြစ်ပါတယ်ရှင်။"}]},{"title":"5. Inquiring Origin with ''มาจากไหน'' (maa jaak nǎi)","titleMyanmar":"အရပ်ဒေသမေးမြန်းခြင်း- ''มาจากไหน'' (မာကျာ့တ်ဏိုင် - ဘယ်ကလာသလဲ)","explanation":"Place ''มาจาก'' (maa jaak - come from) before the interogative pronoun ''ไหน'' (nǎi - where) to build an origin inquiry.","explanationMyanmar":"လာရာအရပ်ကို မေးမြန်းရန်အတွက် ''มาจาก'' (မှ လာသည်) နောက်တွင် ''ไหน'' (ဘယ်မှာ/ဘယ်က) ကို ပေါင်းစပ်ပြီး ''มาจากไหน'' ဟု အသုံးပြုရသည်။","examples":[{"thai":"มาจากไหนคะ","phonetic":"maa jaak nǎi khá","english":"Where do you come from?","myanmar":"ဘယ်ကလာလဲရှင်။"},{"thai":"มาจากพม่าครับ","phonetic":"maa jaak pha-maa khráp","english":"I come from Myanmar.","myanmar":"မြန်မာပြည်က လာပါတယ်ခင်ဗျာ။"},{"thai":"มาจากย่างกุ้งค่ะ","phonetic":"maa jaak jâaŋ-kûŋ khâ","english":"I come from Yangon.","myanmar":"ရန်ကုန်က လာပါတယ်ရှင်။"},{"thai":"แฟนมาจากไหนครับ","phonetic":"faen maa jaak nǎi khráp","english":"Where is your partner from?","myanmar":"မင်းအိမ်ထောင်ဖက်က ဘယ်ကလာလဲခင်ဗျာ။"},{"thai":"พ่อแม่มาจากไหนคะ","phonetic":"phɔ̂ɔ-mɛ̂ɛ maa jaak nǎi khá","english":"Where do your parents come from?","myanmar":"မိဘတွေက ဘယ်ကလာလဲရှင်။"},{"thai":"มาจากต่างจังหวัดครับ","phonetic":"maa jaak tàaŋ-caŋ-wàt khráp","english":"I come from another province.","myanmar":"နယ်က လာတာပါခင်ဗျာ။"}]},{"title":"6. Declaring Country or Nationality using ''คน'' (khon)","titleMyanmar":"လူမျိုးနှင့်နိုင်ငံညွှန်ပြခြင်း- ''คน'' (ခွန် - လူ) + နိုင်ငံအမည်","explanation":"Place ''คน'' (khon - person) directly before any country name to declare a person''s nationality.","explanationMyanmar":"မည်သည့်လူမျိုး/နိုင်ငံသားဖြစ်ကြောင်း ပြောရန် ''คน'' (ခွန် - လူ) ၏ နောက်တွင် သက်ဆိုင်ရာ နိုင်ငံအမည်ကို တိုက်ရိုက်ကပ်ထည့်ရသည်။","examples":[{"thai":"ฉันเป็นคนพม่าค่ะ","phonetic":"chǎn pen khon pha-maa khâ","english":"I am Myanmar nationality.","myanmar":"ကျွန်မ မြန်မာလူမျိုး/နိုင်ငံသား ဖြစ်ပါတယ်ရှင်။"},{"thai":"เขาเป็นคนไทยครับ","phonetic":"khǎo pen khon thaj khráp","english":"He is Thai nationality.","myanmar":"သူက ထိုင်းလူမျိုး ဖြစ်ပါတယ်ခင်ဗျာ။"},{"thai":"คุณเป็นคนพม่าใช่ไหมครับ","phonetic":"khun pen khon pha-maa châj mǎi khráp","english":"Are you a Myanmar national?","myanmar":"မင်းက မြန်မာလူမျိုး ဟုတ်တယ်မလားခင်ဗျာ။"},{"thai":"เพื่อนเป็นคนจีนค่ะ","phonetic":"phʉ̂an pen khon ciin khâ","english":"My friend is Chinese.","myanmar":"သူငယ်ချင်းက တရုတ်လူမျိုး ဖြစ်ပါတယ်ရှင်။"},{"thai":"เจ้านายเป็นคนญี่ปุ่นครับ","phonetic":"câo-naaj pen khon jîi-pùn khráp","english":"My boss is Japanese.","myanmar":"အလုပ်ရှင်က ဂျပန်လူမျိုး ဖြစ်ပါတယ်ခင်ဗျာ။"},{"thai":"เราเป็นคนอาเซียน","phonetic":"raw pen khon aa-sian","english":"We are ASEAN citizens.","myanmar":"ငါတို့က အာဆီယံ နိုင်ငံသားတွေ ဖြစ်တယ်။"}]},{"title":"7. Simple Interrogative ''อะไร'' (a-rai) for Objects/Inquiry","titleMyanmar":"အခြေခံအမေးစကားလုံး ''อะไร'' (အာရိုင် - ဘာလဲ/ဘာ)","explanation":"The word ''อะไร'' (a-rai) is placed at the end of verb phrases to ask ''What''.","explanationMyanmar":"စုံစမ်းမေးမြန်းမှုများ ပြုလုပ်ရာတွင် ''ဘာလဲ'' ဟု မေးလိုပါက ဝါကျ၏ ကြိယာ သို့မဟုတ် နာမ်နောက်တွင် ''อะไร'' ကို ထည့်သွင်းမေးမြန်းရသည်။","examples":[{"thai":"นี่คืออะไรครับ","phonetic":"nîi khʉʉ a-rai khráp","english":"What is this?","myanmar":"ဒါ ဘာလဲခင်ဗျာ။"},{"thai":"นั่นคืออะไรคะ","phonetic":"nân khʉʉ a-rai khá","english":"What is that?","myanmar":"ဟိုဟာ ဘာလဲရှင်။"},{"thai":"คุณพูดอะไรครับ","phonetic":"khun phûut a-rai khráp","english":"What did you say?","myanmar":"မင်း ဘာပြောလိုက်တာလဲခင်ဗျာ။"},{"thai":"ชอบกินอะไรคะ","phonetic":"chɔ̂ɔp kin a-rai khá","english":"What do you like to eat?","myanmar":"ဘာစားရတာ ကြိုက်လဲရှင်။"},{"thai":"ทำงานอะไรครับ","phonetic":"tham-ŋaan a-rai khráp","english":"What job do you do?","myanmar":"ဘာအလုပ်လုပ်လဲခင်ဗျာ။"},{"thai":"หาอะไรอยู่คะ","phonetic":"hǎa a-rai jùu khá","english":"What are you looking for?","myanmar":"ဘာရှာနေတာလဲရှင်။"}]},{"title":"8. Seeking Confirmation with ''ใช่ไหม'' (châj mǎi)","titleMyanmar":"ဟုတ်ပါသလားဟု စိစစ်မေးမြန်းခြင်း- ''ใช่ไหม'' (ချိုက်မိုင် - ဟုတ်တယ်မလား)","explanation":"Place ''ใช่ไหม'' (châj-mǎi) at the end of statements to ask ''Is that right?'' or ''...isn''t it?''.","explanationMyanmar":"မိမိယူဆချက် တစ်ခုကို ဟုတ်/မဟုတ် ထပ်ဆင့်အတည်ပြုချက် တောင်းခံလိုလျှင် ဝါကျအဆုံးတွင် ''ใช่ไหม'' (ဟုတ်တယ်မလား) ကို သုံးရသည်။","examples":[{"thai":"คุณคือมินใช่ไหมครับ","phonetic":"khun khʉʉ min châj mǎi khráp","english":"You are Min, right?","myanmar":"မင်းက မင်း ဟုတ်တယ်မလားခင်ဗျာ။"},{"thai":"นี่คือรถของคุณใช่ไหมคะ","phonetic":"nîi khʉʉ rót khɔ̌ɔŋ khun châj mǎi khá","english":"Is this your car?","myanmar":"ဒါ မင်းကား ဟုတ်တယ်မလားရှင်။"},{"thai":"เข้าใจใช่ไหมครับ","phonetic":"khâo-cay châj mǎi khráp","english":"You understand, correct?","myanmar":"နားလည်တယ် မဟုတ်လားခင်ဗျာ။"},{"thai":"มาจากพม่าใช่ไหมคะ","phonetic":"maa jaak pha-maa châj mǎi khá","english":"You come from Myanmar, right?","myanmar":"မြန်မာပြည်က လာတာ ဟုတ်တယ်မလားရှင်။"},{"thai":"ทำงานที่นี่ใช่ไหมครับ","phonetic":"tham-ŋaan thîi nîi châj mǎi khráp","english":"You work here, correct?","myanmar":"ဒီမှာ အလုပ်လုပ်တာ ဟုတ်တယ်မလားခင်ဗျာ။"},{"thai":"อาหารเผ็ดใช่ไหมคะ","phonetic":"aa-hǎan phèt châj mǎi khá","english":"The food is spicy, isn''t it?","myanmar":"ဟင်းက စပ်တယ် မဟုတ်လားရှင်။"}]},{"title":"9. Polite Greeting ''ยินดีที่ได้รู้จัก'' (yin-dii thîi dâaj rúu-càk)","titleMyanmar":"ဝမ်းမြောက်စွာနှုတ်ဆက်ခြင်း- ''ยินดีที่ได้รู้จัก'' (ယင်ဒီထီးဒိုက်ရူးချက် - တွေ့ရတာ ဝမ်းသာပါတယ်)","explanation":"This is the standard polite greeting for introducing oneself to fresh acquaintances.","explanationMyanmar":"လူတစ်ဦးနှင့် အသစ်စတင် မိတ်ဆက်ချိန်တွင် ရိုးရာအရ ပြောလေ့ရှိသည့်အသုံးမှာ ''ยินดีที่ได้รู้จัก'' (တွေ့ဆုံရတာ ဝမ်းသာပါတယ်) ဖြစ်သည်။","examples":[{"thai":"ยินดีที่ได้รู้จักครับ","phonetic":"yin-dii thîi dâaj rúu-càk khráp","english":"Nice to meet you (male).","myanmar":"တွေ့ရတာ ဝမ်းသာပါတယ်ခင်ဗျာ။"},{"thai":"ยินดีที่ได้รู้จักค่ะ","phonetic":"yin-dii thîi dâaj rúu-càk khâ","english":"Nice to meet you (female).","myanmar":"တွေ့ရတာ ဝမ်းသာပါတယ်ရှင်။"},{"thai":"ยินดีที่ได้พบกันครับ","phonetic":"yin-dii thîi dâaj phóp kan khráp","english":"Good to meet you of late.","myanmar":"ဆုံတွေ့ရတာ ဝမ်းသာပါတယ်ခင်ဗျာ။"},{"thai":"เช่นกันค่ะ","phonetic":"chên kan khâ","english":"Likewise / Same here (female).","myanmar":"ကျွန်မလည်း အတူတူပါပဲရှင်။"},{"thai":"ยินดีที่ได้คุยด้วยครับ","phonetic":"yin-dii thîi dâaj khuy dûaj khráp","english":"Glad to talk to you.","myanmar":"စကားပြောခွင့်ရတာ ဝမ်းသာပါတယ်ခင်ဗျာ။"},{"thai":"ยินดีอย่างยิ่งค่ะ","phonetic":"yin-dii jàaŋ jîŋ khâ","english":"Totally pleased to meet you.","myanmar":"အလွန်ဝမ်းမြောက်မိပါတယ်ရှင်။"}]},{"title":"10. Respectful Departure with ''ขอตัวก่อน'' (khɔ̌ɔ tua kɔ̀ɔn)","titleMyanmar":"ရိုသေစွာနှုတ်ဆက်ခွင့်တောင်းခြင်း- ''ขอตัวก่อน'' (ခေါတူအာကွန် - ခွင့်ပြုပါဦး/ပြန်ပါဦးမယ်)","explanation":"Politely excuse yourself from a group or conversation using ''ขอตัวก่อน'' (khɔ̌ɔ tua kɔ̀ɔn - excuse my body first).","explanationMyanmar":"စကားပြောဆိုနေစဉ် သို့မဟုတ် အများကြားမှ ခေတ္တခွာလိုသောအခါ သို့မဟုတ် ပြန်လိုသောအခါ ''ขอตัวก่อน'' ဟု သုံးစွဲနှုတ်ဆက်ရသည်။","examples":[{"thai":"ผมขอตัวก่อนครับ","phonetic":"phǒm khɔ̌ɔ tua kɔ̀ɔn khráp","english":"I will take my leave now (male).","myanmar":"ကျွန်တော် ပြန်ခွင့်ပြုပါဦးခင်ဗျာ။"},{"thai":"ฉันขอตัวก่อนค่ะ","phonetic":"chǎn khɔ̌ɔ tua kɔ̀ɔn khâ","english":"I will take my leave now (female).","myanmar":"ကျွန်မ ပြန်ခွင့်ပြုပါဦးရှင်။"},{"thai":"ขอตัวไปทำงานก่อนนะครับ","phonetic":"khɔ̌ɔ tua paj tham-ŋaan kɔ̀ɔn ná khráp","english":"Let me go to work now, okay?","myanmar":"အလုပ်သွားလုပ်ခွင့်ပြုပါဦးနော်ခင်ဗျာ။"},{"thai":"พรุ่งนี้เจอกันครับ","phonetic":"phrûŋ-níi cəə kan khráp","english":"See you tomorrow.","myanmar":"မနက်ဖြန်မှ တွေ့ကြမယ်ခင်ဗျာ။"},{"thai":"ขอตัวสักครู่นะคะ","phonetic":"khɔ̌ɔ tua sàk-khrûu ná khá","english":"Excuse me for a moment, okay?","myanmar":"ခဏလောက် ခွင့်ပြုပါဦးနော်ရှင်။"},{"thai":"กลับก่อนนะค่ะ","phonetic":"klàp kɔ̀ɔn ná khâ","english":"I''m heading back first.","myanmar":"ပြန်နှင့်ပါရစေဦးနော်ရှင်။"}]}]',
    '[{"id":"1_gen_w_th_mm_คุณ_idx_0","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"คุณ\" (khun)?","options":["သင် / မင်း","ရှစ်ဆယ့်နှစ် / ၈၂","အတည်ပြုသည် / သဘောတူသည်","အစည်းအဝေး ဆုံးဖြတ်ချက်"],"correctAnswer":"သင် / မင်း","explanation":"\"คุณ\" (khun) registers in English as \"you / Mr. / Ms.\".","explanationMyanmar":"\"คุณ\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"သင် / မင်း\" (pronoun) ဖြစ်သည်။"},{"id":"1_gen_w_th_mm_ชื่อ_idx_1","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"ชื่อ\" (chue)?","options":["အရင်က / အရင်လာသည်","နာမည် / အမည်","မီးလောင်သည် / မီးလောင်မှု","လိုအပ်ချက်ကို ဖြည့်ဆည်းပေးသည်"],"correctAnswer":"နာမည် / အမည်","explanation":"\"ชื่อ\" (chue) registers in English as \"name / to be named\".","explanationMyanmar":"\"ชื่อ\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"နာမည် / အမည်\" (noun) ဖြစ်သည်။"},{"id":"1_gen_w_th_mm_อะไร_idx_2","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"อะไร\" (a-rai)?","options":["ဘိလပ်မြေ","ဖွင့်သည်","ဘာလဲ","ရှစ်ဆယ့်နှစ် / ၈၂"],"correctAnswer":"ဘာလဲ","explanation":"\"อะไร\" (a-rai) registers in English as \"what\".","explanationMyanmar":"\"อะไร\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ဘာလဲ\" (pronoun) ဖြစ်သည်။"},{"id":"1_gen_w_th_mm_ครับ_idx_3","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"ครับ\" (khráp)?","options":["နှစ်ထောင် / ၂,၀၀၀","ခင်ဗျာ","ငွေသွင်းသည် / အပ်နှံသည်","ယူသွားလိုက်ပါ"],"correctAnswer":"ခင်ဗျာ","explanation":"\"ครับ\" (khráp) registers in English as \"polite particle (male)\".","explanationMyanmar":"\"ครับ\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ခင်ဗျာ\" (particle) ဖြစ်သည်။"},{"id":"1_gen_w_th_mm_ผม_idx_4","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"ผม\" (phom)?","options":["ကြိုးစားသည်","ကျွန်တော်","ဖြည့်စွက် / နောက်ထပ်","ကြက်သားထမင်းကြော်"],"correctAnswer":"ကျွန်တော်","explanation":"\"ผม\" (phom) registers in English as \"I (male)\".","explanationMyanmar":"\"ผม\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ကျွန်တော်\" (pronoun) ဖြစ်သည်။"},{"id":"1_gen_w_th_mm_มิน_idx_5","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"มิน\" (Min)?","options":["ထဲ၌ရှိသည် / ထဲမှာ","ပြီးစီးသွားသော","မင်း","ဖြည့်စွက် / နောက်ထပ်"],"correctAnswer":"မင်း","explanation":"\"มิน\" (Min) registers in English as \"Min (name)\".","explanationMyanmar":"\"มิน\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"မင်း\" (proper noun) ဖြစ်သည်။"},{"id":"1_gen_w_th_mm_มาจาก_idx_6","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"มาจาก\" (maa jaak)?","options":["သုံးဆယ် / ၃၀","ကတ်နှိပ်သည် / လက်မှတ်ထိုးသည်","မှ လာသည်","ရေလောင်းသည်"],"correctAnswer":"မှ လာသည်","explanation":"\"มาจาก\" (maa jaak) registers in English as \"come from\".","explanationMyanmar":"\"มาจาก\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"မှ လာသည်\" (verb) ဖြစ်သည်။"},{"id":"1_gen_w_th_mm_ไหน_idx_7","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"ไหน\" (nai)?","options":["ဘယ် / ဘယ်မှာ","သုံးလပတ်","ပြီးပါပြီ / ပြီးစီးပါပြီ","ငွေလဲနှုန်း / ပေါက်ဈေး"],"correctAnswer":"ဘယ် / ဘယ်မှာ","explanation":"\"ไหน\" (nai) registers in English as \"where\".","explanationMyanmar":"\"ไหน\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ဘယ် / ဘယ်မှာ\" (pronoun) ဖြစ်သည်။"},{"id":"1_gen_w_th_mm_คะ_idx_8","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"คะ\" (khá)?","options":["နှစ်ထောင် / ၂,၀၀၀","ရှင်","ရည်းစား / အိမ်ထောင်ဖက်","ငွေလဲနှုန်း / ပေါက်ဈေး"],"correctAnswer":"ရှင်","explanation":"\"คะ\" (khá) registers in English as \"polite particle for question (female)\".","explanationMyanmar":"\"คะ\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ရှင်\" (particle) ဖြစ်သည်။"},{"id":"1_gen_w_th_mm_พม่า_idx_9","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"พม่า\" (pha-maa)?","options":["အမျှော်အမြင် ကြီးမားသော","ပူးပေါင်းဆောင်ရွက်သည်","မြန်မာ","နှစ်ထောင် / ၂,၀၀၀"],"correctAnswer":"မြန်မာ","explanation":"\"พม่า\" (pha-maa) registers in English as \"Myanmar\".","explanationMyanmar":"\"พม่า\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"မြန်မာ\" (noun) ဖြစ်သည်။"},{"id":"1_gen_w_th_mm_ค่ะ_idx_10","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"ค่ะ\" (khâ)?","options":["ခေါင်းဆောင်","ဓား","အနာဂတ်","ရှင်"],"correctAnswer":"ရှင်","explanation":"\"ค่ะ\" (khâ) registers in English as \"polite particle for statement (female)\".","explanationMyanmar":"\"ค่ะ\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ရှင်\" (particle) ဖြစ်သည်။"},{"id":"1_gen_w_mm_th_คุณ_idx_11","type":"translate-mm-to-thai","prompt":"How do you express \"သင် / မင်း\" in Thai vocabulary?","options":["กี่ (kee)","เอา (ao)","บัญชี (ban-chee)","คุณ (khun)"],"correctAnswer":"คุณ (khun)","explanation":"\"คุณ\" is the vocabulary item representing \"you / Mr. / Ms.\".","explanationMyanmar":"\"သင် / မင်း\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"คุณ\" (khun) ဖြစ်သည်။"},{"id":"1_gen_w_mm_th_ชื่อ_idx_12","type":"translate-mm-to-thai","prompt":"How do you express \"နာမည် / အမည်\" in Thai vocabulary?","options":["มีด (meet)","พยายาม (pha-yaa-yaam)","ปุ่ม (pum)","ชื่อ (chue)"],"correctAnswer":"ชื่อ (chue)","explanation":"\"ชื่อ\" is the vocabulary item representing \"name / to be named\".","explanationMyanmar":"\"နာမည် / အမည်\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"ชื่อ\" (chue) ဖြစ်သည်။"},{"id":"1_gen_w_mm_th_อะไร_idx_13","type":"translate-mm-to-thai","prompt":"How do you express \"ဘာလဲ\" in Thai vocabulary?","options":["สองพัน (song phan)","อะไร (a-rai)","ประจำปี (pra-cham pee)","ไม่มี (mai mee)"],"correctAnswer":"อะไร (a-rai)","explanation":"\"อะไร\" is the vocabulary item representing \"what\".","explanationMyanmar":"\"ဘာလဲ\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"อะไร\" (a-rai) ဖြစ်သည်။"},{"id":"1_gen_w_mm_th_ครับ_idx_14","type":"translate-mm-to-thai","prompt":"How do you express \"ခင်ဗျာ\" in Thai vocabulary?","options":["ครับ (khráp)","จาน (jaan)","คุณ (khun)","สัญญา (san-yaa)"],"correctAnswer":"ครับ (khráp)","explanation":"\"ครับ\" is the vocabulary item representing \"polite particle (male)\".","explanationMyanmar":"\"ခင်ဗျာ\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"ครับ\" (khráp) ဖြစ်သည်။"},{"id":"1_gen_w_mm_th_ผม_idx_15","type":"translate-mm-to-thai","prompt":"How do you express \"ကျွန်တော်\" in Thai vocabulary?","options":["แจ้ง (jaeng)","ตลาด (ta-laat)","ผม (phom)","สัญญา (san-yaa)"],"correctAnswer":"ผม (phom)","explanation":"\"ผม\" is the vocabulary item representing \"I (male)\".","explanationMyanmar":"\"ကျွန်တော်\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"ผม\" (phom) ဖြစ်သည်။"},{"id":"1_gen_w_mm_th_มิน_idx_16","type":"translate-mm-to-thai","prompt":"How do you express \"မင်း\" in Thai vocabulary?","options":["แปดสิบสอง (paet-sip-song)","มิน (Min)","ฉุกเฉิน (chuk-choen)","ประจำปี (pra-cham pee)"],"correctAnswer":"มิน (Min)","explanation":"\"มิน\" is the vocabulary item representing \"Min (name)\".","explanationMyanmar":"\"မင်း\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"มิน\" (Min) ဖြစ်သည်။"},{"id":"1_gen_w_mm_th_มาจาก_idx_17","type":"translate-mm-to-thai","prompt":"How do you express \"မှ လာသည်\" in Thai vocabulary?","options":["มาจาก (maa jaak)","ตัวนี้ (tua nee)","ตอนนี้ (ton-nee)","มีความสุข (mee khwaam-sook)"],"correctAnswer":"มาจาก (maa jaak)","explanation":"\"มาจาก\" is the vocabulary item representing \"come from\".","explanationMyanmar":"\"မှ လာသည်\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"มาจาก\" (maa jaak) ဖြစ်သည်။"},{"id":"1_gen_w_mm_th_ไหน_idx_18","type":"translate-mm-to-thai","prompt":"How do you express \"ဘယ် / ဘယ်မှာ\" in Thai vocabulary?","options":["ศักยภาพ (sak-ya-phaap)","ฟังใหม่ (fang mai)","ไหน (nai)","จะ (ja)"],"correctAnswer":"ไหน (nai)","explanation":"\"ไหน\" is the vocabulary item representing \"where\".","explanationMyanmar":"\"ဘယ် / ဘယ်မှာ\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"ไหน\" (nai) ဖြစ်သည်။"},{"id":"1_gen_w_mm_th_คะ_idx_19","type":"translate-mm-to-thai","prompt":"How do you express \"ရှင်\" in Thai vocabulary?","options":["คะ (khá)","วิสัยทัศน์ (wi-sai-that)","เรทเงิน (rate nguen)","ผัก (phak)"],"correctAnswer":"คะ (khá)","explanation":"\"คะ\" is the vocabulary item representing \"polite particle for question (female)\".","explanationMyanmar":"\"ရှင်\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"คะ\" (khá) ဖြစ်သည်။"}]'
