INSERT OR REPLACE INTO lessons (id, course_id, title_thai, title_phonetic, title_english, title_myanmar, dialogue, grammar, quizzes) VALUES (
    '',
    'course-basic',
    'ครอบครัวและความสัมพันธ์',
    'khrɔ̂ɔp-khrua lɛ́ khwaam sǎm-phan',
    'Lesson 2: Family and Relationships',
    'သင်ခန်းစာ ၂ - မိသားစုနှင့် ပတ်သက်သော စကားလုံးများ',
    '[{"speaker":"A","thai":"มีแฟนหรือยังครับ","phonetic":"mee faen rue yang khráp","english":"Do you have a boyfriend/girlfriend yet?","myanmar":"ရည်းစား/အိမ်ထောင်ဖက် ရှိပြီလားခင်ဗျာ။","words":[{"thai":"มี","phonetic":"mee","english":"to have","myanmar":"ရှိသည်","partOfSpeech":"verb"},{"thai":"แฟน","phonetic":"faen","english":"boyfriend / girlfriend / spouse","myanmar":"ရည်းစား / အိမ်ထောင်ဖက်","partOfSpeech":"noun"},{"thai":"หรือยัง","phonetic":"rue yang","english":"or not yet? / yet?","myanmar":"ပြီးပြီလား","partOfSpeech":"particle"}]},{"speaker":"B","thai":"ยังไม่มีค่ะ","phonetic":"yang mai mee khâ","english":"I do not have one yet.","myanmar":"မရှိသေးပါဘူးရှင်။","words":[{"thai":"ยัง","phonetic":"yang","english":"yet / still","myanmar":"သေးသည် / အခုထက်ထိ","partOfSpeech":"adverb"},{"thai":"ไม่มี","phonetic":"mai mee","english":"don''t have","myanmar":"မရှိပါဘူး","partOfSpeech":"verb"}]},{"speaker":"A","thai":"มีลูกกี่คนครับ","phonetic":"mee luuk kee khon khráp","english":"How many children do you have?","myanmar":"သားသမီး ဘယ်နှစ်ယောက်ရှိလဲခင်ဗျာ။","words":[{"thai":"ลูก","phonetic":"luuk","english":"child / children","myanmar":"သားသမီး / ကလေး","partOfSpeech":"noun"},{"thai":"กี่","phonetic":"kee","english":"how many","myanmar":"ဘယ်နှစ်","partOfSpeech":"adjective"},{"thai":"คน","phonetic":"khon","english":"people / classifier for people","myanmar":"ယောက်","partOfSpeech":"classifier"}]},{"speaker":"B","thai":"มีลูกสองคนครับ","phonetic":"mee luuk song khon khráp","english":"I have two children.","myanmar":"ကလေး နှစ်ယောက်ရှိပါတယ်ခင်ဗျာ။","words":[{"thai":"สอง","phonetic":"song","english":"two","myanmar":"နှစ် / ၂","partOfSpeech":"number"}]}]',
    '[{"title":"1. Expressing Possession with particle ''ของ'' (khɔ̌ɔŋ)","titleMyanmar":"ပိုင်ဆိုင်မှုပြ အသုံးအနှုန်း- ''ของ'' (ခေါင် - ၏ / ရဲ့)","explanation":"To show possession, place ''ของ'' (khɔ̌ɔŋ) in front of the pronoun or owner noun.","explanationMyanmar":"ပိုင်ဆိုင်မှုကို ပြသလိုသောအခါ [ပိုင်ဆိုင်သည့်အရာ] + ''ของ'' (ခေါင်) + [ပိုင်ရှင်] ပုံစံအတိုင်း ရေးသားသုံးစွဲရသည်။","examples":[{"thai":"รถของผม","phonetic":"rót khɔ̌ɔŋ phǒm","english":"My car (car of mine).","myanmar":"ကျွန်တော့်ရဲ့ ကား။"},{"thai":"บ้านของเจ้านาย","phonetic":"bâan khɔ̌ɔŋ câo-naaj","english":"The boss''s house.","myanmar":"အလုပ်ရှင်ရဲ့ အိမ်။"},{"thai":"โทรศัพท์ของใครครับ","phonetic":"thoo-rá-sàp khɔ̌ɔŋ khraj khráp","english":"Whose phone is this?","myanmar":"ဒါ ဘယ်သူ့ဖုန်းလဲခင်ဗျာ။"},{"thai":"นั่นคือแฟนของฉันค่ะ","phonetic":"nân khʉʉ faen khɔ̌ɔŋ chǎn khâ","english":"That is my partner (female).","myanmar":"ဟိုဟာ ကျွန်မရဲ့ အိမ်ထောင်ဖက်/ရည်းစား ဖြစ်ပါတယ်ရှင်။"},{"thai":"หนังสือของเธอ","phonetic":"nǎŋ-sʉ̌ʉ khɔ̌ɔŋ thəə","english":"Her book.","myanmar":"သူမရဲ့ စာအုပ်။"},{"thai":"นี่ของมินใช่ไหมครับ","phonetic":"nîi khɔ̌ɔŋ min châj mǎi khráp","english":"Is this Min''s property?","myanmar":"ဒါ မင်းရဲ့ဟာ ဟုတ်တယ်မလားခင်ဗျာ။"}]},{"title":"2. Declaring Possession or Existence with ''มี'' (mee)","titleMyanmar":"ရှိခြင်း/ပိုင်ဆိုင်ခြင်း ဖော်ပြပုံ- ''มี'' (မီ - ရှိသည်)","explanation":"''มี'' (mee) means ''to have'' or ''there is/are'' and is placed directly before the object or noun.","explanationMyanmar":"ပိုင်ဆိုင်မှု သို့မဟုတ် တည်ရှိမှုကို ပြသရန် ''มี'' (မီ) ကို အသုံးပြုပြီး၊ ''ရှိသည်'' ဟု အဓိပ္ပာယ်ရသည်။","examples":[{"thai":"ผมมีแฟนแล้วครับ","phonetic":"phǒm mee faen lɛ́ɛw khráp","english":"I have a partner already.","myanmar":"ကျွန်တော့်မှာ ရည်းစား/အိမ်ထောင်ရှိပြီခင်ဗျာ။"},{"thai":"มีพี่น้องแปดคนค่ะ","phonetic":"mee pîi-nɔ́ɔŋ pɛ̀ɛt khon khâ","english":"I have 8 siblings.","myanmar":"ကျွန်မမှာ မောင်နှမ ၈ ယောက် ရှိပါတယ်ရှင်။"},{"thai":"ที่นี่มีน้ำไหมครับ","phonetic":"thîi nîi mee náam mǎi khráp","english":"Is there water here?","myanmar":"ဒီမှာ ရေရှိလားခင်ဗျာ။"},{"thai":"ฉันไม่มีเวลาค่ะ","phonetic":"chǎn mâj mee wee-laa khâ","english":"I do not have time (female).","myanmar":"ကျွန်မမှာ အချိန်မရှိပါဘူးရှင်။"},{"thai":"คุณมีสิทธิ์อะไร","phonetic":"khun mee sìt a-rai","english":"What right do you have?","myanmar":"မင်းမှာ ဘာအခွင့်အရေးရှိလို့လဲ။"},{"thai":"ห้องนี้มีแอร์ไหมครับ","phonetic":"hɔ̂ŋ níi mee ɛɛ mǎi khráp","english":"Does this room have aircon?","myanmar":"ဒီအခန်းမှာ အဲကွန်းရှိလားခင်ဗျာ။"}]},{"title":"3. Explaining Still/Not Yet boundary using ''ยังไม่'' (jaŋ mâj)","titleMyanmar":"မပြီးပြတ်သေးသည့် အခြေအနေ- ''ยังไม่'' (ယန်းမိုင့် - မ...သေးပါဘူး)","explanation":"''ยังไม่'' (jaŋ mâj) combines ''ยัง'' (yet/still) and ''ไม่'' (not) to negate actions that might take place in future.","explanationMyanmar":"တစ်စုံတစ်ခုကို လက်ရှိအချိန်အထိ မလုပ်ဆောင်ရသေးကြောင်းကို ''ยังไม่'' (မ...သေးပါ) ဟု သုံးနှုန်းဖော်ပြရသည်။","examples":[{"thai":"ยังไม่มีชื่อครับ","phonetic":"jaŋ mâj mee chʉ̂ʉ khráp","english":"We don''t have a name yet.","myanmar":"နာမည် မရှိသေးပါဘူးခင်ဗျာ။"},{"thai":"ฉันยังไม่หิวค่ะ","phonetic":"chǎn jaŋ mâj hǐw khâ","english":"I am not hungry yet.","myanmar":"ကျွန်မ မဆာသေးပါဘူးရှင်။"},{"thai":"หัวหน้ายังไม่มาครับ","phonetic":"hǔa-nâa jaŋ mâj maa khráp","english":"The boss hasn''t come yet.","myanmar":"หัวหน้า (အလုပ်ရှင်) မလာသေးပါဘူးခင်ဗျာ။"},{"thai":"ยังไม่เสร็จค่ะ","phonetic":"jaŋ mâj sèt khâ","english":"It is not finished yet.","myanmar":"မပြီးသေးပါဘူးရှင်။"},{"thai":"ผมยังไม่กลับบ้านครับ","phonetic":"phǒm jaŋ mâj klàp bâan khráp","english":"I am not going home yet.","myanmar":"ကျွန်တော် အိမ်မပြန်သေးပါဘူးခင်ဗျာ။"},{"thai":"เขายังไม่เข้าใจคะ","phonetic":"khǎo jaŋ mâj khâo-cay khá","english":"They do not understand yet.","myanmar":"သူ နားမလည်သေးပါဘူးရှင်။"}]},{"title":"4. Kinship Status Prefixes: ''พี่'' (pîi) and ''น้อง'' (nɔ́ɔŋ)","titleMyanmar":"နှုတ်ဆက်ရာတွင် ဆွေမျိုးစဉ်ဆက် သုံးစွဲပုံ- ''พี่'' (ဖီး - အစ်ကို/အစ်မ) နှင့် ''น้อง'' (နောင် - မောင်/ညီမ)","explanation":"Place ''พี่'' (pîi) before older peers, and ''น้อง'' (nɔ́ɔŋ) before younger ones as respectful pronouns or titles.","explanationMyanmar":"မိမိထက်ကြီးသူကို ''พี่'' (အစ်ကို/အစ်မ) ဟု ရှေ့ကခေါ်ပြီး၊ ငယ်သူကို ''น้อง'' (ညီ/ညီမ) ဟု ချစ်ခင်လေးစားစွာ တွဲခေါ်သည်။","examples":[{"thai":"พี่แดงสบายดีไหมครับ","phonetic":"pîi dɛɛŋ sa-baaj-dii mǎi khráp","english":"Brother Daeng, are you doing fine?","myanmar":"အစ်ကိုဒိန်း နေကောင်းလားခင်ဗျာ။"},{"thai":"น้องฝนกินข้าวหรือยังคะ","phonetic":"nɔ́ɔŋ fǒn kin khâaw rʉ̌ʉ-jaŋ khá","english":"Little sister Fon, have you eaten yet?","myanmar":"ညီမလေးဖုန်း ထမင်းစားပြီးပြီလားရှင်။"},{"thai":"พี่ชายทำงานที่ไหนครับ","phonetic":"pîi-chaaj tham-ŋaan thîi nǎi khráp","english":"Where does your older brother work?","myanmar":"အစ်ကိုကြီး ဘယ်မှာ အလုပ်လုပ်လဲခင်ဗျာ။"},{"thai":"น้องสาวเรียนหนังสืออยู่ค่ะ","phonetic":"nɔ́ɔŋ-sǎaw rian nǎŋ-sʉ̌ʉ jùu khâ","english":"My younger sister is studying.","myanmar":"ညီမလေးက စာသင်နေပါတယ်ရှင်။"},{"thai":"ขอบคุณมากค่ะพี่","phonetic":"khɔ̀ɔp-khun mâak khâ pîi","english":"Thank you very much, brother/sister.","myanmar":"ကျေးဇူးအများကြီးတင်ပါတယ် အစ်ကို/အစ်မရှင်။"},{"thai":"ไม่เป็นไรครับน้อง","phonetic":"mâj pen raj khráp nɔ́ɔŋ","english":"No problem at all, little one.","myanmar":"ကိစ္စမရှိပါဘူး ညီလေး/ညီမလေးရာ။"}]},{"title":"5. Multi-person Classifier ''คน'' (khon) in Counting Siblings","titleMyanmar":"လူဦးရေ ရေတွက်သည့် အမျိုးအစားပြ နာမ်- ''คน'' (ခွန် - ယောက်)","explanation":"When counting human family members, the classifier ''คน'' (khon - people) must follow the exact number.","explanationMyanmar":"လူအင်အား သို့မဟုတ် မိသားစုဝင်ဦးရေကို ရေတွက်ဖော်ပြသည့်အခါ ဂဏန်းနောက်တွင် ''คน'' (ယောက်) ကို ထည့်သွင်းပေးရသည်။","examples":[{"thai":"ผมมีลูกสามคนครับ","phonetic":"phǒm mee lûuk sǎam khon khráp","english":"I have 3 children.","myanmar":"ကျွန်တော့်မှာ သားသမီး ၃ ယောက် ရှိပါတယ်ခင်ဗျာ။"},{"thai":"เขามีเพื่อนร่วมงานสี่คนค่ะ","phonetic":"khǎo mee phʉ̂an rûam ŋaan sìi khon khâ","english":"She has four coworkers.","myanmar":"သူ့မှာ လုပ်ဖော်ကိုင်ဖက် ၄ ယောက် ရှိပါတယ်ရှင်။"},{"thai":"พวกเรามีหกคนครับ","phonetic":"phûak raw mee hòk khon khráp","english":"There are six of us.","myanmar":"ကျွန်တော်တို့ အားလုံး ၆ ယောက် ရှိပါတယ်ခင်ဗျာ။"},{"thai":"มีพี่น้องเจ็ดคนคะ","phonetic":"mee pîi-nɔ́ɔŋ cèt khon khá","english":"I have seven siblings.","myanmar":"မောင်နှမ ၇ ယောက် ရှိပါတယ်ရှင်။"},{"thai":"เจ้านายเห็นคนสองคนครับ","phonetic":"câo-naaj hěn khon sɔ̌ɔŋ khon khráp","english":"The boss saw two people.","myanmar":"အလုပ်ရှင်က လူနှစ်ယောက် မြင်လိုက်တယ်။"},{"thai":"พนักงานสิบคน","phonetic":"phá-nák-ŋaan sìp khon","english":"ten employees / workers","myanmar":"ဝန်ထမ်း ၁၀ ယောက်"}]},{"title":"6. Quantitative Question Interrogative ''กี่'' (kìi)","titleMyanmar":"အရေအတွက်မေးခွန်း- ''กี่'' (ကီး - ဘယ်နှစ်...လဲ)","explanation":"Place ''กี่'' (kìi) before a classifier to formulate queries about quantities or counts.","explanationMyanmar":"မည်မျှ သို့မဟုတ် ဘယ်နှစ်ခု ရှိပါသလဲဟု အရေအတွက် မေးမြန်းလိုလျှင် ''กี่'' ကို အမျိုးအစားပြနာမ်၏ ရှေ့တွင် ထားရသည်။","examples":[{"thai":"มีลูกกี่คนครับ","phonetic":"mee lûuk kìi khon khráp","english":"How many children do you have?","myanmar":"သားသမီး ဘယ်နှစ်ယောက် ရှိပါသလဲခင်ဗျာ။"},{"thai":"คุณอายุกี่ปีคะ","phonetic":"khun aa-jú kìi pii khá","english":"How many years old are you?","myanmar":"အသက် ဘယ်နှစ်နှစ် ရှိပြီလဲရှင်။"},{"thai":"ทำงานกี่ชั่วโมงครับ","phonetic":"tham-ŋaan kìi chûa-mooŋ khráp","english":"How many hours do you work?","myanmar":"အလုပ် ဘယ်နှစ်နာရီ လုပ်ရသလဲခင်ဗျာ။"},{"thai":"มีกี่ห้องค่ะ","phonetic":"mee kìi hɔ̂ŋ khâ","english":"How many rooms are there?","myanmar":"ဘယ်နှစ်ခန်း ရှိလဲရှင်။"},{"thai":"ราคากี่บาทคะ","phonetic":"raa-khaa kìi bàat khá","english":"How many Baht is the price?","myanmar":"ဈေး ဘယ်နှစ်ဘတ်လဲရှင်။"},{"thai":"คุณต้องการกี่ชิ้นครับ","phonetic":"khun tɔ̂ɔŋ-kaan kìi chín khráp","english":"How many pieces do you require?","myanmar":"မင်း ဘယ်နှစ်ချပ်/ဘယ်နှစ်ခု လိုအပ်လဲခင်ဗျာ။"}]},{"title":"7. Expressing Marital Status with ''แต่งงานแล้ว'' (tɛ̀ŋ-ŋaan lɛ́ɛw)","titleMyanmar":"အိမ်ထောင်ရေးအခြေအနေ ဖော်ပြမှု- ''แต่งงานแล้ว'' (တန်းငန်းလဲဝ်း - အိမ်ထောင်ပြုပြီးပြီ)","explanation":"''แต่งงาน'' (tɛ̀ŋ-ŋaan) means to marry. Append ''แล้ว'' (already) to state that one is married.","explanationMyanmar":"အိမ်ထောင်ရှိကြောင်း ပြောဆိုရန် ''แต่งงาน'' (မင်္ဂလာဆောင်သည်) နောက်တွင် ''แล้ว'' (ပြီးပြီ) ကို တွဲလျက် သုံးနှုန်းရသည်။","examples":[{"thai":"ผมแต่งงานแล้วครับ","phonetic":"phǒm tɛ̀ŋ-ŋaan lɛ́ɛw khráp","english":"I am married (male).","myanmar":"ကျွန်တော် အိမ်ထောင်ရှိပါပြီခင်ဗျာ။"},{"thai":"ฉันแต่งงานแล้วค่ะ","phonetic":"chǎn tɛ̀ŋ-ŋaan lɛ́ɛw khâ","english":"I am married (female).","myanmar":"ကျွန်မ အိမ်ထောင်ရှိပါပြီရှင်။"},{"thai":"แต่งงานหรือยังครับ","phonetic":"tɛ̀ŋ-ŋaan rʉ̌ʉ jaŋ khráp","english":"Are you married yet?","myanmar":"အိမ်ထောင်ပြုပြီးပြီလားခင်ဗျာ။"},{"thai":"เขายังไม่แต่งงานค่ะ","phonetic":"khǎo jaŋ mâj tɛ̀ŋ-ŋaan khâ","english":"He/She is not married yet.","myanmar":"သူ အိမ်ထောင်မရှိသေးပါဘူးရှင်။"},{"thai":"อยากแต่งงานปีนี้ครับ","phonetic":"jàak tɛ̀ŋ-ŋaan pii níi khráp","english":"I want to marry this year.","myanmar":"ဒီနှစ်ထဲ မင်္ဂလာဆောင်ချင်တယ်ခင်ဗျာ။"},{"thai":"เพื่อนของผมแต่งงานแล้ว","phonetic":"phʉ̂an khɔ̌ɔŋ phǒm tɛ̀ŋ-ŋaan lɛ́ɛw","english":"My friend is married.","myanmar":"ကျွန်တော့်သူငယ်ချင်း အိမ်ထောင်ကျသွားပြီ။"}]},{"title":"8. The Alternative/Disjunctive Conjunction ''หรือ'' (rʉ̌ʉ)","titleMyanmar":"စကားလုံးရွေးချယ်မှုဆိုင်ရာ စကားဆက်- ''หรือ'' (လု - သို့မဟုတ် / ...လား)","explanation":"''หรือ'' (rʉ̌ʉ) serves as ''or'' to list alternative options or to ask questions looking for choices.","explanationMyanmar":"အကြောင်းအရာ နှစ်ခုအနက် တစ်ခုကို ရွေးချယ်ရန် သို့မဟုတ် ''သို့မဟုတ်'' ဟု မေးလိုသောအခါ ၎င်းစကားဆက်ကို သုံးသည်။","examples":[{"thai":"ชาหรือกาแฟดีครับ","phonetic":"chaa rʉ̌ʉ kaa-fɛɛ dii khráp","english":"Tea or coffee?","myanmar":"ရေနွေးကြမ်းလား ကော်ဖီလားခင်ဗျာ။"},{"thai":"ส้มหรือแอปเปิ้ลคะ","phonetic":"sôm rʉ̌ʉ ɛ́p-pə̂n khá","english":"Oranges or apples?","myanmar":"လိမ္မော်သီးလား ပန်းသီးလားရှင်။"},{"thai":"ไปวันนี้หรือพรุ่งนี้ครับ","phonetic":"paj wan-níi rʉ̌ʉ phrûŋ-níi khráp","english":"Going today or tomorrow?","myanmar":"ဒီနေ့သွားမှာလား ဒါမှမဟုတ် မနက်ဖြန်လားခင်ဗျာ။"},{"thai":"เขาเป็นคนไทยหรือคนพม่าคะ","phonetic":"khǎo pen khon thaj rʉ̌ʉ khon pha-maa khá","english":"Is he Thai or Myanmar?","myanmar":"သူက ထိုင်းလူမျိုးလား မြန်မာလူမျိုးလားရှင်။"},{"thai":"โทรศัพท์หรือเงินสดดีครับ","phonetic":"thoo-rá-sàp rʉ̌ʉ ŋən-sòt dii khráp","english":"Phone transfer or cash?","myanmar":"ဖုန်းငွေလွှဲမလား ဒါမှမဟုတ် လက်ငင်းပိုက်ဆံလားခင်ဗျာ။"},{"thai":"รักฉันหรือรักเขา","phonetic":"rák chǎn rʉ̌ʉ rák khǎo","english":"Do you love me or them?","myanmar":"ကျွန်မကို ချစ်သလား ဒါမှမဟုတ် သူ့ကိုလား။"}]},{"title":"9. Specifying Kinship Subclasses: ''ลูก'' (lûuk)","titleMyanmar":"သားသမီးများကို ခွဲခြားခေါ်ဝေါ်ပုံ- ''ลูก'' (လုတ့် - သားသမီး)","explanation":"Use ''ลูก'' (lûuk) as the base term and append gender flags like ''ชาย'' (chaaj) or ''สาว'' (sǎaw) to modify.","explanationMyanmar":"သားသမီးကို ''ลูก'' (လုတ့်) ဟုခေါ်ပြီး၊ ကျားမ ခွဲခြားရန် ''ลูกชาย'' (သား) သို့မဟုတ် ''ลูกสาว'' (သမီး) ဟု သတ်မှတ်သည်။","examples":[{"thai":"ผมมีลูกชายหนึ่งคนครับ","phonetic":"phǒm mee lûuk-chaaj nʉ̀ŋ khon khráp","english":"I have one son.","myanmar":"ကျွန်တော့်မှာ သားတစ်ယောက် ရှိပါတယ်ခင်ဗျာ။"},{"thai":"เธอมีลูกสาวสองคนค่ะ","phonetic":"thəə mee lûuk-sǎaw sɔ̌ɔŋ khon khâ","english":"She has two daughters.","myanmar":"သူမမှာ သမီးနှစ်ယောက် ရှိပါတယ်ရှင်။"},{"thai":"ลูกชายอายุเก้าปีแล้วครับ","phonetic":"lûuk-chaaj aa-jú kâaw pii lɛ́ɛw khráp","english":"My son is nine years old already.","myanmar":"ကျွန်တော့်သားက အသက် ၉ နှစ် ရှိပြီခင်ဗျာ။"},{"thai":"ลูกสาวเรียนเก่งมากค่ะ","phonetic":"lûuk-sǎaw rian kèŋ mâak khâ","english":"My daughter is very smart in school.","myanmar":"သမီးလေးက စာအရမ်းတော်တယ်ရှင်။"},{"thai":"ลูกของเขาชื่ออะไรครับ","phonetic":"lûuk khɔ̌ɔŋ khǎo chʉ̂ʉ a-rai khráp","english":"What is their child''s name?","myanmar":"သူ့ကလေးနာမည် ဘာလဲခင်ဗျာ။"},{"thai":"รักลูกทุกคนครับ","phonetic":"rák lûuk thúk khon khráp","english":"I love all my children.","myanmar":"သားသမီးတိုင်းကို ချစ်ပါတယ်ခင်ဗျာ။"}]},{"title":"10. Comprehensive Compound Kinship Terms","titleMyanmar":"မိသားစုစုပေါင်းအသုံးအနှုန်း- ''พ่อแม่'' (ဖောမေး - မိဘ)","explanation":"Thai groups parents and compound family relationships together natively by merging nouns.","explanationMyanmar":"ထိုင်းဘာသာစကားတွင် မိခင်ဖခင်ကို ပေါင်းစပ်ပြီး ''พ่อแม่'' (မိဘ) ဟု တစ်စုတစ်စည်းတည်း သုံးနှုန်းကြသည်။","examples":[{"thai":"พ่อแม่ของผมอยู่พม่าครับ","phonetic":"phɔ̂ɔ-mɛ̂ɛ khɔ̌ɔŋ phǒm jùu pha-maa khráp","english":"My parents live in Myanmar.","myanmar":"ကျွန်တော့်မိဘတွေက မြန်မာပြည်မှာ နေပါတယ်ခင်ဗျာ။"},{"thai":"ฉันรักพ่อแม่มากค่ะ","phonetic":"chǎn rák phɔ̂ɔ-mɛ̂ɛ mâak khâ","english":"I love my parents very much.","myanmar":"ကျွန်မ မိဘတွေကို အရမ်းချစ်တယ်ရှင်။"},{"thai":"พ่อแม่สบายดีไหมครับ","phonetic":"phɔ̂ɔ-mɛ̂ɛ sa-baaj-dii mǎi khráp","english":"Are your parents doing fine?","myanmar":"မိဘတွေ နေကောင်းကြရဲ့လားခင်ဗျာ။"},{"thai":"พ่อทำงานที่โรงงานค่ะ","phonetic":"phɔ̂ɔ tham-ŋaan thîi rooŋ-ŋaan khâ","english":"My father works in a factory.","myanmar":"ဖေဖေက စက်ရုံမှာ အလုပ်လုပ်ပါတယ်ရှင်။"},{"thai":"แม่ทำอาหารอร่อยมากครับ","phonetic":"mɛ̂ɛ tham aa-hǎan a-rɔ̀j mâak khráp","english":"My mother cooks very delicious food.","myanmar":"မေမေချက်တဲ့ဟင်းက အရမ်းစားကောင်းတယ်ခင်ဗျာ။"},{"thai":"ครอบครัวมีความสุขมาก","phonetic":"khrɔ̂ɔp-khrua mee khwaam-sùk mâak","english":"The family is very happy.","myanmar":"မိသားစုက တကယ့်ကို ပျော်ရွှင်စရာ ကောင်းလှပါတယ်။"}]}]',
    '[{"id":"2_gen_w_th_mm_มี_idx_0","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"มี\" (mee)?","options":["အစိမ်းရောင်","ရှိသည်","ပြီးပြီလား","နားမမှီလိုက်ပါဘူး / နားမလည်လိုက်ပါဘူး"],"correctAnswer":"ရှိသည်","explanation":"\"มี\" (mee) registers in English as \"to have\".","explanationMyanmar":"\"มี\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ရှိသည်\" (verb) ဖြစ်သည်။"},{"id":"2_gen_w_th_mm_แฟน_idx_1","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"แฟน\" (faen)?","options":["ပေးပါ / ကျေးဇူးပြုပြီး","လာသည်","ရည်းစား / အိမ်ထောင်ဖက်","ရှစ်ဆယ် / ၈၀"],"correctAnswer":"ရည်းစား / အိမ်ထောင်ဖက်","explanation":"\"แฟน\" (faen) registers in English as \"boyfriend / girlfriend / spouse\".","explanationMyanmar":"\"แฟน\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ရည်းစား / အိမ်ထောင်ဖက်\" (noun) ဖြစ်သည်။"},{"id":"2_gen_w_th_mm_หรือยัง_idx_2","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"หรือยัง\" (rue yang)?","options":["ခလုတ်","ပြီးပြီလား","ပူးပေါင်းဆောင်ရွက်သည်","စာရွက်စာတမ်း"],"correctAnswer":"ပြီးပြီလား","explanation":"\"หรือยัง\" (rue yang) registers in English as \"or not yet? / yet?\".","explanationMyanmar":"\"หรือยัง\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ပြီးပြီလား\" (particle) ဖြစ်သည်။"},{"id":"2_gen_w_th_mm_ยัง_idx_3","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"ยัง\" (yang)?","options":["ဖိနပ်","သေးသည် / အခုထက်ထိ","ဖြစ်သည် / ပေါ်ပေါက်သည်","အကဲဖြတ်သည်"],"correctAnswer":"သေးသည် / အခုထက်ထိ","explanation":"\"ยัง\" (yang) registers in English as \"yet / still\".","explanationMyanmar":"\"ยัง\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"သေးသည် / အခုထက်ထိ\" (adverb) ဖြစ်သည်။"},{"id":"2_gen_w_th_mm_ไม่มี_idx_4","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"ไม่มี\" (mai mee)?","options":["ရော့ပါ / ဒီမှာပါ","ဘယ်နှစ်ဘတ်လဲ","မရှိပါဘူး","ကယ်ကြပါဦး / ကူညီပါဦး"],"correctAnswer":"မရှိပါဘူး","explanation":"\"ไม่มี\" (mai mee) registers in English as \"don''t have\".","explanationMyanmar":"\"ไม่มี\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"မရှိပါဘူး\" (verb) ဖြစ်သည်။"},{"id":"2_gen_w_th_mm_ลูก_idx_5","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"ลูก\" (luuk)?","options":["စွန့်စားရမှု / အန္တရာယ်","သားသမီး / ကလေး","လူနာ / ဒဏ်ရာရရှိသူ","စီ / တစ်...ဆီ"],"correctAnswer":"သားသမီး / ကလေး","explanation":"\"ลูก\" (luuk) registers in English as \"child / children\".","explanationMyanmar":"\"ลูก\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"သားသမီး / ကလေး\" (noun) ဖြစ်သည်။"},{"id":"2_gen_w_th_mm_กี่_idx_6","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"กี่\" (kee)?","options":["ဘယ်နှစ်","အထည်ချုပ်သည်","ရေသန့် / ရိုးရိုးရေ","ဒီနေရာမှာ"],"correctAnswer":"ဘယ်နှစ်","explanation":"\"กี่\" (kee) registers in English as \"how many\".","explanationMyanmar":"\"กี่\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ဘယ်နှစ်\" (adjective) ဖြစ်သည်။"},{"id":"2_gen_w_th_mm_คน_idx_7","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"คน\" (khon)?","options":["ရေရှည်","မနက် / မနက်ခင်း","ယောက်","ကျွန်တော်ကိုယ်တိုင် / ကျွန်တော်ပါပဲ"],"correctAnswer":"ယောက်","explanation":"\"คน\" (khon) registers in English as \"people / classifier for people\".","explanationMyanmar":"\"คน\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"ယောက်\" (classifier) ဖြစ်သည်။"},{"id":"2_gen_w_th_mm_สอง_idx_8","type":"translate-thai-to-mm","prompt":"What is the Myanmar meaning of the Thai word/phrase: \"สอง\" (song)?","options":["နှစ် / ၂","အရေးပေါ်","ပြဿနာရှိသည်","လေး / ၄"],"correctAnswer":"နှစ် / ၂","explanation":"\"สอง\" (song) registers in English as \"two\".","explanationMyanmar":"\"สอง\" ၏ မြန်မာအဓိပ္ပာယ်မှာ \"နှစ် / ၂\" (number) ဖြစ်သည်။"},{"id":"2_gen_w_mm_th_มี_idx_9","type":"translate-mm-to-thai","prompt":"How do you express \"ရှိသည်\" in Thai vocabulary?","options":["มี (mee)","มีปัญหา (mee pan-haa)","นโยบาย (na-yo-baai)","รับอะไรดี (rap a-rai dee)"],"correctAnswer":"มี (mee)","explanation":"\"มี\" is the vocabulary item representing \"to have\".","explanationMyanmar":"\"ရှိသည်\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"มี\" (mee) ဖြစ်သည်။"},{"id":"2_gen_w_mm_th_แฟน_idx_10","type":"translate-mm-to-thai","prompt":"How do you express \"ရည်းစား / အိမ်ထောင်ဖက်\" in Thai vocabulary?","options":["เครื่อง (khruang)","กี่ชิ้น (kee chin)","ยังไง (yang-ngai)","แฟน (faen)"],"correctAnswer":"แฟน (faen)","explanation":"\"แฟน\" is the vocabulary item representing \"boyfriend / girlfriend / spouse\".","explanationMyanmar":"\"ရည်းစား / အိမ်ထောင်ဖက်\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"แฟน\" (faen) ဖြစ်သည်။"},{"id":"2_gen_w_mm_th_หรือยัง_idx_11","type":"translate-mm-to-thai","prompt":"How do you express \"ပြီးပြီလား\" in Thai vocabulary?","options":["ความเสี่ยง (khwaam-siang)","โทรหา (thor haa)","สีเขียว (see-khiao)","หรือยัง (rue yang)"],"correctAnswer":"หรือยัง (rue yang)","explanation":"\"หรือยัง\" is the vocabulary item representing \"or not yet? / yet?\".","explanationMyanmar":"\"ပြီးပြီလား\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"หรือยัง\" (rue yang) ဖြစ်သည်။"},{"id":"2_gen_w_mm_th_ยัง_idx_12","type":"translate-mm-to-thai","prompt":"How do you express \"သေးသည် / အခုထက်ထိ\" in Thai vocabulary?","options":["ตรวจสอบ (troat-soab)","ตรงโน้น (trong noon)","สี่ (see)","ยัง (yang)"],"correctAnswer":"ยัง (yang)","explanation":"\"ยัง\" is the vocabulary item representing \"yet / still\".","explanationMyanmar":"\"သေးသည် / အခုထက်ထိ\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"ยัง\" (yang) ဖြစ်သည်။"},{"id":"2_gen_w_mm_th_ไม่มี_idx_13","type":"translate-mm-to-thai","prompt":"How do you express \"မရှိပါဘူး\" in Thai vocabulary?","options":["เข้าบ้าน (khao baan)","กี่บาท (kee baat)","ไม่มี (mai mee)","เก้า (kao)"],"correctAnswer":"ไม่มี (mai mee)","explanation":"\"ไม่มี\" is the vocabulary item representing \"don''t have\".","explanationMyanmar":"\"မရှိပါဘူး\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"ไม่มี\" (mai mee) ဖြစ်သည်။"},{"id":"2_gen_w_mm_th_ลูก_idx_14","type":"translate-mm-to-thai","prompt":"How do you express \"သားသမီး / ကလေး\" in Thai vocabulary?","options":["ลูก (luuk)","แข็งแกร่ง (khaeng-kraeng)","รักษาสุขภาพ (rak-saa suk-kha-phaap)","ปูน (puun)"],"correctAnswer":"ลูก (luuk)","explanation":"\"ลูก\" is the vocabulary item representing \"child / children\".","explanationMyanmar":"\"သားသမီး / ကလေး\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"ลูก\" (luuk) ဖြစ်သည်။"},{"id":"2_gen_w_mm_th_กี่_idx_15","type":"translate-mm-to-thai","prompt":"How do you express \"ဘယ်နှစ်\" in Thai vocabulary?","options":["ใส่ (sai)","กี่ (kee)","ดีมาก (dee-maak)","ศุลกากร (son-la-kaa-kon)"],"correctAnswer":"กี่ (kee)","explanation":"\"กี่\" is the vocabulary item representing \"how many\".","explanationMyanmar":"\"ဘယ်နှစ်\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"กี่\" (kee) ဖြစ်သည်။"},{"id":"2_gen_w_mm_th_คน_idx_16","type":"translate-mm-to-thai","prompt":"How do you express \"ယောက်\" in Thai vocabulary?","options":["เดือนละ (duan la)","ผมเอง (phom eng)","คน (khon)","ช้าๆ (chaa-chaa)"],"correctAnswer":"คน (khon)","explanation":"\"คน\" is the vocabulary item representing \"people / classifier for people\".","explanationMyanmar":"\"ယောက်\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"คน\" (khon) ဖြစ်သည်။"},{"id":"2_gen_w_mm_th_สอง_idx_17","type":"translate-mm-to-thai","prompt":"How do you express \"နှစ် / ၂\" in Thai vocabulary?","options":["สองชั่วโมง (song chua-mong)","สอง (song)","สี่ (see)","พันธมิตร (phan-tha-mit)"],"correctAnswer":"สอง (song)","explanation":"\"สอง\" is the vocabulary item representing \"two\".","explanationMyanmar":"\"နှစ် / ၂\" အတွက် သက်ဆိုင်ရာ ထိုင်းစကားလုံးမှာ \"สอง\" (song) ဖြစ်သည်။"},{"id":"2_gen_list_w_มี_idx_18","type":"listening-match","prompt":"Listen to the audio pronunciation carefully and select the correct translation:","promptThai":"มี","options":["ရှိသည်","ငါးရာ","ရှင်","အသုံးစရိတ်"],"correctAnswer":"ရှိသည်","explanation":"The audio spoken is \"มี\" (mee), which means \"to have\".","explanationMyanmar":"အသံထွက်မှာ \"มี\" (mee) ဖြစ်ပြီး ၎င်းမှာ \"ရှိသည်\" ဖြစ်သည်။"},{"id":"2_gen_fg_มีแฟนหรื_idx_19","type":"fill-gap","prompt":"Complete the blank in the sentence: \"มี_______หรือยังครับ\"\n(Topic: \"Do you have a boyfriend/girlfriend yet?\" / \"ရည်းစား/အိမ်ထောင်ဖက် ရှိပြီလားခင်ဗျာ။\")","options":["เคย","ขับเคลื่อน","ฟังไม่ทัน","แฟน"],"correctAnswer":"แฟน","explanation":"The full correct sentence is: \"มีแฟนหรือยังครับ\" (mee faen rue yang khráp).","explanationMyanmar":"ကွက်လပ်ဖြည့်ပြီးနောက် ဝါကျအပြည့်အစုံမှာ \"มีแฟนหรือยังครับ\" (mee faen rue yang khráp) ဖြစ်သည်။"}]'
  );
