INSERT OR REPLACE INTO lessons (id, course_id, title_thai, title_phonetic, title_english, title_myanmar, dialogue, grammar, quizzes) VALUES (
    '',
    'course-basic',
    'อาหารและเครื่องดื่ม',
    'aa-hǎan lɛ́ khruaŋ-dʉ̀ʉm',
    'Lesson 10: Food & Drinks',
    'သင်ခန်းစာ ၁၀ - အစားအစာ၊ အဖျော်ယမကာနှင့် မှာယူခြင်း',
    '[{"speaker":"A","thai":"ข้าวผัดไก่จานกี่บาทครับ","phonetic":"khaao-phat kai jaan kee baat khráp","english":"How much is a plate of chicken fried rice?","myanmar":"ကြက်သားထမင်းကြော်တစ်ပွဲဘယ်လောက်လဲခင်ဗျာ။","words":[{"thai":"ข้าวผัดไก่","phonetic":"khaao-phat kai","english":"chicken fried rice","myanmar":"ကြက်သားထမင်းကြော်","partOfSpeech":"noun"},{"thai":"จาน","phonetic":"jaan","english":"plate / classifier for plates","myanmar":"ပွဲ / ချပ်","partOfSpeech":"classifier"},{"thai":"กี่บาท","phonetic":"kee baat","english":"how many Baht?","myanmar":"ဘယ်နှစ်ဘတ်လဲ","partOfSpeech":"phrase"}]},{"speaker":"B","thai":"จานละสี่สิบบาทครับ","phonetic":"jaan la see-sip baat khráp","english":"It is forty Baht per plate.","myanmar":"တစ်ပွဲကို ၄၀ ဘတ်ပါခင်ဗျာ။","words":[{"thai":"ละ","phonetic":"la","english":"per / each","myanmar":"စီ / တစ်...ဆီ","partOfSpeech":"preposition"},{"thai":"สี่สิบ","phonetic":"see-sip","english":"forty (40)","myanmar":"လေးဆယ် / ၄၀","partOfSpeech":"number"}]},{"speaker":"A","thai":"ขอน้ำเปล่าหนึ่งขวดค่ะ","phonetic":"kho naam plao nueng khuat khâ","english":"May I have a bottle of plain water?","myanmar":"ရေသန့်တစ်ပုလင်း ပေးပါရှင်။","words":[{"thai":"น้ำเปล่า","phonetic":"naam plao","english":"plain water / drinking water","myanmar":"ရေသန့် / ရိုးရိုးရေ","partOfSpeech":"noun"},{"thai":"หนึ่งขวด","phonetic":"nueng khuat","english":"one bottle","myanmar":"တစ်ပုလင်း","partOfSpeech":"phrase"}]},{"speaker":"B","thai":"นี่ค่ะ น้ำเย็นๆ","phonetic":"nee khâ, naam yen-yen","english":"Here it is, cold water.","myanmar":"ရော့ပါရှင်၊ ရေအေးအေးလေးပါ။","words":[{"thai":"น้ำเย็น","phonetic":"naam yen","english":"cold water","myanmar":"ရေအေး / ရေခဲရေ","partOfSpeech":"noun"}]}]',
