INSERT OR REPLACE INTO lessons (id, course_id, title_thai, title_phonetic, title_english, title_myanmar, dialogue, grammar, quizzes) VALUES (
    '',
    'course-basic',
    'ภาษาไทยในที่ทำงานขั้นสูงและการรายงาน',
    'phaa-sǎa thaj naj thîi-tham-ngaan khân sǔuŋ lɛ́ kaan raaj-ŋaan',
    'Lesson 25: Advanced Workplace Thai',
    'သင်ခန်းစာ ၂၅ - အဆင့်မြင့် လုပ်ငန်းခွင်သုံးနှင့် အစီရင်ခံခြင်း',
    '[{"speaker":"A","thai":"วันนี้ทำได้กี่ชิ้นแล้วครับ","phonetic":"wan-nee tham-dai kee chin laeo khráp","english":"How many pieces have you made today?","myanmar":"ဒီနေ့ ဘယ်နှစ်ခု လုပ်ပြီးပြီလဲခင်ဗျာ။","words":[{"thai":"ทำได้","phonetic":"tham-dai","english":"can make / achieved","myanmar":"လုပ်ပြီးပြီ / လုပ်နိုင်သည်","partOfSpeech":"phrase"},{"thai":"กี่ชิ้น","phonetic":"kee chin","english":"how many pieces?","myanmar":"ဘယ်နှစ်ခုလဲ / ဘယ်နှစ်ထည်လဲ","partOfSpeech":"phrase"},{"thai":"ชิ้น","phonetic":"chin","english":"piece / classifier for objects","myanmar":"ခု / ထည်","partOfSpeech":"classifier"}]},{"speaker":"B","thai":"ทำได้ห้าร้อยชิ้นแล้วครับ","phonetic":"tham-dai haa-roi chin laeo khráp","english":"I have made five hundred pieces already.","myanmar":"ငါးရာ (၅၀၀) ခု လုပ်ပြီးပါပြီခင်ဗျာ။","words":[{"thai":"ห้าร้อย","phonetic":"haa-roi","english":"five hundred (500)","myanmar":"ငါးရာ / ၅၀၀","partOfSpeech":"number"}]},{"speaker":"A","thai":"ของขาด ส่งรายงานหรือยัง","phonetic":"khong khaat, song raai-ngaan rue yang","english":"Materials are short. Have you sent the report yet?","myanmar":"ပစ္စည်းလိုနေတာ အစီရင်ခံစာ ပို့ပြီးပြီလား။","words":[{"thai":"ของขาด","phonetic":"khong khaat","english":"materials missing / out of stock","myanmar":"ပစ္စည်းလိုသည် / ပစ္စည်းပြတ်လပ်သည်","partOfSpeech":"phrase"},{"thai":"ส่งรายงาน","phonetic":"song raai-ngaan","english":"to send/submit report","myanmar":"အစီရင်ခံစာပို့သည်","partOfSpeech":"verb"}]},{"speaker":"B","thai":"ส่งแล้วครับ แจ้งเถ้าแก่แล้ว","phonetic":"song laeo khráp, jaeng thao-kae laeo","english":"Already sent. I informed the Boss already.","myanmar":"ပို့ပြီးပါပြီ၊ သူဌေးကိုလည်း အကြောင်းကြားပြီးပါပြီ။","words":[{"thai":"แจ้ง","phonetic":"jaeng","english":"to inform / notify / alert","myanmar":"အကြောင်းကြားသည်","partOfSpeech":"verb"}]}]',
